package com.bank.skew.aqe;

import com.bank.skew.model.KeyPartition;
import java.util.*;
import java.util.logging.Logger;

// Flags partitions skewed per BOTH factor-of-median AND absolute byte threshold.
public class SkewDetector {
    private static final Logger log = Logger.getLogger(SkewDetector.class.getName());
    private final int factor;
    private final long thresholdBytes;

    public SkewDetector(int factor, long thresholdBytes) {
        this.factor = factor;
        this.thresholdBytes = thresholdBytes;
    }

    public List<KeyPartition> detect(List<KeyPartition> parts) {
        long median = median(parts);
        List<KeyPartition> skewed = new ArrayList<>();
        for (KeyPartition p : parts) {
            boolean relative = p.getBytes() > (long) factor * median;
            boolean absolute = p.getBytes() > thresholdBytes;
            if (relative && absolute) {
                log.warning(() -> "SKEW detected: key '" + p.getKey() + "' " + p.getBytes()
                        + "B (median=" + median + ", >" + factor + "x AND >threshold)");
                skewed.add(p);
            }
        }
        return skewed;
    }

    private long median(List<KeyPartition> parts) {
        List<Long> sizes = new ArrayList<>();
        for (KeyPartition p : parts) sizes.add(p.getBytes());
        Collections.sort(sizes);
        return sizes.get(sizes.size() / 2);
    }
}
