package com.bank.skew.aqe;

import com.bank.skew.model.KeyPartition;
import java.util.*;
import java.util.logging.Logger;

// Splits a skewed partition and replicates the other (dimension) side.
public class SkewSplitter {
    private static final Logger log = Logger.getLogger(SkewSplitter.class.getName());
    private final long targetBytes;

    public SkewSplitter(long targetBytes) { this.targetBytes = targetBytes; }

    public List<KeyPartition> split(KeyPartition skewed, int dimensionRows) {
        int splits = (int) Math.ceil((double) skewed.getBytes() / targetBytes);
        long each = skewed.getBytes() / splits;
        List<KeyPartition> subs = new ArrayList<>();
        for (int i = 0; i < splits; i++) {
            subs.add(new KeyPartition(skewed.getKey() + "#sub" + i, each));
        }
        // Replicate the matching dimension rows into EACH sub-partition for correctness.
        log.info(() -> "split '" + skewed.getKey() + "' into " + splits
                + " sub-partitions; replicate " + dimensionRows
                + " dimension rows into each (join stays correct)");
        return subs;
    }
}
