package com.bank.skew.manual;

import java.util.*;
import java.util.logging.Logger;

// Manual fallback: salt an extreme key so ONE logical key becomes MANY physical keys.
public class Salter {
    private static final Logger log = Logger.getLogger(Salter.class.getName());
    private final int saltBuckets;
    private final Random rnd = new Random(7);

    public Salter(int saltBuckets) { this.saltBuckets = saltBuckets; }

    // Fact side: append a random salt so the mega key spreads across buckets.
    public List<String> saltFactKeys(String megaKey, int rows) {
        List<String> salted = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            salted.add(megaKey + "_" + rnd.nextInt(saltBuckets));
        }
        log.info(() -> "salted fact key '" + megaKey + "' across " + saltBuckets + " buckets");
        return salted;
    }

    // Dimension side: expand the single row into one copy per salt bucket.
    public List<String> expandDimensionKey(String megaKey) {
        List<String> expanded = new ArrayList<>();
        for (int b = 0; b < saltBuckets; b++) expanded.add(megaKey + "_" + b);
        log.info(() -> "expanded dimension key '" + megaKey + "' into "
                + saltBuckets + " salted copies (so the join still matches)");
        return expanded;
    }
}
