package com.bank.skew;

import com.bank.skew.aqe.*;
import com.bank.skew.manual.Salter;
import com.bank.skew.model.KeyPartition;
import java.util.List;
import java.util.logging.*;

public class SkewDemo {
    private static final Logger log = Logger.getLogger(SkewDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new SkewLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Join-key partitions: normal accounts small, one corporate account huge.
        List<KeyPartition> parts = List.of(
            new KeyPartition("SAV2001", 20_000_000),   // Rajesh
            new KeyPartition("CUR3001", 18_000_000),   // Priya
            new KeyPartition("CORP9999", 1_000_000_000) // corporate mega-account (skew)
        );

        // AQE: detect and split the skewed partition, replicate the other side.
        var skewed = new SkewDetector(5, 268_435_456).detect(parts);
        for (KeyPartition s : skewed) {
            new SkewSplitter(256_000_000).split(s, /*dimensionRows*/ 1);
        }

        // When AQE isn't enough (one key dominates even after split) → salting.
        log.info("CORP9999 still dominates even after split → apply manual salting");
        Salter salter = new Salter(8);
        salter.saltFactKeys("CORP9999", 5);
        salter.expandDimensionKey("CORP9999");
    }
}

